from pathlib import Path
p=Path(__file__).with_name('admin.js')
t=p.read_text(encoding='utf-8')
t=t.replace("for(const n of ['x','y','w','h'])numberIn(patch.rect[n],n==='w'||n==='h'?0.000001:0,1,n);if(!['viewport','local'].includes(patch.rect.mode))throw Error('定位方式无效');", "if(!['viewport','local'].includes(patch.rect.mode))throw Error('定位方式无效');const local=patch.rect.mode==='local';for(const n of ['x','y','w','h'])numberIn(patch.rect[n],n==='w'||n==='h'?0.001:local?-5:-1,local?5:2,n);")
t=t.replace("if(typeof v!=='string'||v.length>100||/[<>;{}]|url\\s*\\(|expression\\s*\\(/i.test(v))throw Error('颜色值无效');", "if(typeof v!=='string'||v.length>100||!(/^(?:#[0-9a-f]{3}|#[0-9a-f]{4}|#[0-9a-f]{6}|#[0-9a-f]{8}|rgba?\\([0-9.,%\\s]+\\))$/i.test(v)))throw Error('颜色仅支持十六进制或rgb/rgba格式');")
t=t.replace("name==='borderRadius'?100:1000", "name==='borderRadius'?200:10000")
t=t.replace("[A-Za-z0-9_.:-]{1,120}", "[A-Za-z0-9_.:-]{1,40}")
t=t.replace("else if(typeof v!=='string'||v.length>500)throw Error('对象文字字段无效');", "else if(typeof v!=='string'||v.length>(name==='label'?200:name==='location'?300:name==='group'?100:40))throw Error('对象文字字段无效');")
t=t.replace("clamp=(n,min=0)=>Math.max(min,Math.min(1,n));return {x:clamp(values.x/width),y:clamp(values.y/height),w:clamp(values.w/width,1/width),h:clamp(values.h/height,1/height),mode};", "clamp=(n,min,max)=>Math.max(min,Math.min(max,n)),limit=mode==='local'?5:2,minimum=mode==='local'?-5:-1;return {x:clamp(values.x/width,minimum,limit),y:clamp(values.y/height,minimum,limit),w:clamp(values.w/width,0.001,limit),h:clamp(values.h/height,0.001,limit),mode};")
t=t.replace("Math.min(1000,Math.max(0", "Math.min(10000,Math.max(0")
